default.shell:
$mismatchCount = 0

$key = Get-Item -LiteralPath 'HKLM:\Software\Policies\Microsoft\Windows\Currentversion\Appmodel\Statemanager' -ErrorAction SilentlyContinue
$current = $null
if ($key) { $current = $key.GetValue('AllowSharedLocalAppData', $null, 'DoNotExpandEnvironmentNames') }
if (-not ($current -is [int] -and [BitConverter]::ToUInt32([BitConverter]::GetBytes($current), 0) -eq [uint32]0)) {
    Write-Output 'Mismatch: HKLM:\Software\Policies\Microsoft\Windows\Currentversion\Appmodel\Statemanager [AllowSharedLocalAppData]'
    $mismatchCount++
}

if ($mismatchCount -gt 0) { exit 1 }
exit 0

steps.shell:
$ErrorActionPreference = 'Stop'
trap { Write-Output $_.Exception.Message; exit 1 }

if (-not (Test-Path -LiteralPath 'HKLM:\Software\Policies\Microsoft\Windows\Currentversion\Appmodel\Statemanager')) {
    New-Item -Path 'HKLM:\Software\Policies\Microsoft\Windows\Currentversion\Appmodel\Statemanager' -Force | Out-Null
}
New-ItemProperty -LiteralPath 'HKLM:\Software\Policies\Microsoft\Windows\Currentversion\Appmodel\Statemanager' -Name 'AllowSharedLocalAppData' -Value 0 -PropertyType DWord -Force | Out-Null
exit 0
